extends SceneTree
const SCHEMA = preload("res://PopSpireWomen/animation/rig_schema.gd")
const PUPPET = preload("res://PopSpireWomen/animation/puppet.gd")
var checks := 0
var failures := 0
var records := []
func expect(ok: bool, message: String) -> void:
	checks += 1
	if not ok:
		failures += 1
		push_error(message)
func _initialize() -> void:
	call_deferred("run")
func run() -> void:
	var output := "/tmp/sts2-autonomous/surfaces10/validation"
	for character in ["silent", "ironclad", "regent", "necrobinder", "defect"]:
		for rig_name in ["rig", "rest_rig"]:
			var path := "res://PopSpireWomen/art/%s/%s.json" % [character, rig_name]
			var data: Variant = JSON.parse_string(FileAccess.get_file_as_string(path))
			expect(SCHEMA.validate(data).is_empty(), path + " schema")
			var view := SubViewport.new()
			view.size = Vector2i(1024,1536)
			view.render_target_update_mode = SubViewport.UPDATE_ALWAYS
			root.add_child(view)
			var bg := Polygon2D.new()
			bg.polygon = PackedVector2Array([Vector2(0,0),Vector2(1024,0),Vector2(1024,1536),Vector2(0,1536)])
			bg.color = Color("404758")
			view.add_child(bg)
			var puppet = PUPPET.new()
			view.add_child(puppet)
			expect(puppet.load_rig(path, character.to_upper()), path + " actual texture load " + puppet.last_error)
			if puppet.rig.is_empty():
				view.free()
				continue
			expect(is_equal_approx(puppet.scale.x, 300.0/1536.0), path + " display height")
			var throne: Polygon2D = puppet.get_node_or_null("throne")
			var initial := PackedVector2Array()
			if throne != null: initial = throne.polygon.duplicate()
			var animation := "overgrowth_loop" if rig_name == "rest_rig" else "select"
			for phase in [0.0,0.25,0.5,0.75,1.0]:
				expect(puppet.sample_animation(animation,phase,false,2.0), path + " pose sample")
				for child in puppet.get_children():
					if child is Polygon2D:
						var finite := true
						for p in child.polygon:
							if not is_finite(p.x) or not is_finite(p.y): finite = false
						expect(finite,path + " finite mesh " + child.name)
				if throne != null: expect(throne.polygon == initial, path + " throne root stable")
			if rig_name == "rest_rig":
				for rest in ["overgrowth_loop", "hive_loop", "glory_loop"]:
					expect(puppet.rig.clips.has(rest), path + " explicit quiet " + rest)
					expect(puppet.sample_animation(rest,0.5,true,0.0), path + " reduced motion " + rest)
			puppet.sample_animation(animation,0.5,false,2.0)
			# Native-pixel inspection only; does not alter the shipped display_height.
			puppet.scale = Vector2.ONE
			puppet.position = Vector2(data.origin[0], data.origin[1])
			await process_frame
			await RenderingServer.frame_post_draw
			var shot: String = output + "/" + character + "-" + rig_name + "-render.png"
			expect(view.get_texture().get_image().save_png(shot)==OK, path + " rendered inspection saved")
			records.append({"path":path,"render":shot,"layers":puppet.get_child_count()})
			view.free()
			await process_frame
	var result := {"checks":checks,"failures":failures,"rigs":records,"game_launched":false,"godot":Engine.get_version_info().string}
	var file := FileAccess.open(output + "/godot-results.json", FileAccess.WRITE)
	file.store_string(JSON.stringify(result,"  ")+"\n")
	file.close()
	print("SURFACE_CHECKS=",checks," FAILURES=",failures)
	quit(0 if failures==0 else 1)
